const cName=c=>lang==='en'?c.english:c.name;const planName=id=>t(plans.find(p=>p.id===id)?.name||'غير محدد');const date=s=>s?s.split('-').reverse().join('/'):'—';const money=n=>`${num(n)} ${t('د.ع')}`;const badge=s=>`<span class="status ${esc(s)}">${txt(statusNames[s]||s)}</span>`;const companyCell=c=>`<div class="company-cell"><span class="company-avatar">${esc(cName(c).charAt(0))}</span><div><strong>${esc(cName(c))}</strong><small>${esc(c.id)}</small></div></div>`;
function btn(label,action,id='',kind='secondary',ic=''){return `<button class="btn-${kind}" data-action="${action}" data-id="${esc(id)}">${ic?icon(ic):''}${txt(label)}</button>`}function head(title,sub,actions=''){return `<div class="page-head"><div><h1>${txt(title)}</h1><p>${txt(sub)}</p></div><div class="head-actions">${actions}</div></div>`}function stat(label,value,note,ic,color=''){return `<div class="stat"><div class="stat-top"><span>${txt(label)}</span><span class="stat-icon">${icon(ic)}</span></div><strong>${esc(value)}</strong><small class="${color}">${txt(note)}</small></div>`}function cardHead(title,sub='',extra=''){return `<div class="card-head"><div><h2>${txt(title)}</h2>${sub?`<p>${txt(sub)}</p>`:''}</div>${extra}</div>`}function empty(title,body,ic='info'){return `<div class="empty"><div class="empty-icon">${icon(ic)}</div><h3>${txt(title)}</h3><p>${txt(body)}</p></div>`}function line(k,v){return `<div class="detail-line"><dt>${txt(k)}</dt><dd>${v}</dd></div>`}function field(label,name,value='',type='text',required=false,extra=''){return `<div class="form-field ${extra}"><label for="f-${name}">${txt(label)}${required?' <span class="required">*</span>':''}</label><input id="f-${name}" name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''} ${type==='number'?'min="0"':''}></div>`}function selectField(label,name,options,value=''){return `<div class="form-field"><label for="f-${name}">${txt(label)}</label><select id="f-${name}" name="${name}">${options.map(o=>`<option value="${esc(o[0])}" ${o[0]===value?'selected':''}>${esc(o[1])}</option>`).join('')}</select></div>`}
function toast(s){clearTimeout(toastTimer);$('#toast').textContent=t(s);$('#toast').classList.add('show');toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4500)}function log(action,c){audits.unshift({action,en:en[action]||action,company:c,time:new Date().toLocaleString('en-GB',{timeZone:'Asia/Baghdad'})})}
function nav(){const names=['overview','accounts','subscriptions','plans','billing','usage','servers','integrations','team','audit','settings'];$('#nav').innerHTML=names.map((n,i)=>`${i===6?'<div class="nav-divider"></div>':''}<button class="nav-item ${(page==='account'?'accounts':page)===n?'active':''}" data-page="${n}">${icon(n==='overview'?'dashboard':n==='team'?'users':n)}<span>${txt(n)}</span>${n==='accounts'?`<span class="nav-count">${companies.length}</span>`:''}</button>`).join('')+`<a class="nav-item" href="crm.html">${icon('plans')}<span>${lang==='ar'?'إضافات المؤسسات / CRM':'Organization add-ons / CRM'}</span></a><a class="nav-item" href="forms.html">${icon('plans')}<span>VODNOX FORMS</span></a>`;$$('[data-t]').forEach(e=>e.textContent=t(e.dataset.t));$('#language').textContent=lang==='ar'?'English':'العربية';$('#bell').innerHTML=icon('bell');$('#demoIcon').innerHTML=icon('info')}
function overview(){let totalCalls=companies.reduce((a,c)=>a+c.calls,0);const states=['active','trial','pending','expired','suspended'];return head('نظرة عامة','مراقبة الحسابات وتفعيلها ومتابعة تفاصيل كل شركة.',btn('إضافة حساب','addAccount','','primary','plus'))+`<section class="welcome"><div><small>VODNOX / PLATFORM OVERVIEW</small><h2>${txt('متابعة أعمالك تبدأ من هنا')}</h2><p>${txt('حساباتك واشتراكاتك واتصالاتك. رؤية واحدة لكل ما يهم.')}</p></div><div class="welcome-end"><b>${txt('الأحد، 11/10/2026')}</b><span>${txt('التوقيت: بغداد')}</span></div></section><div class="stats">${stat('إجمالي الحسابات',companies.length,'منها حساب تجريبي','accounts')}${stat('اشتراكات فعّالة',companies.filter(c=>c.status==='active').length,'مفعّلة إدارياً في المعاينة','shield','green')}${stat('تحتاج متابعة',companies.filter(c=>['pending','expired'].includes(c.status)).length,'بانتظار التفعيل أو التجديد','clock','gold')}${stat('المكالمات هذا الشهر',num(totalCalls),'بيانات استخدام تجريبية','phone')}</div><div class="two-col"><section class="card">${cardHead('نمو الحسابات','آخر 6 أشهر · بيانات تجريبية','<span class="tag">05 — 10 / 2026</span>')}<div class="chart-wrap"><svg class="chart" viewBox="0 0 620 180" role="img" aria-label="${txt('حسابات جديدة')}"><defs><linearGradient id="area" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#F7B955" stop-opacity=".18"/><stop offset="1" stop-color="#F7B955" stop-opacity="0"/></linearGradient></defs><path d="M30 25H600M30 65H600M30 105H600M30 145H600" stroke="#edf1f6"/><path d="M30 135C85 135 88 117 144 117S210 97 258 98 329 109 372 75 441 81 486 49 548 56 600 28V145H30Z" fill="url(#area)"/><path d="M30 135C85 135 88 117 144 117S210 97 258 98 329 109 372 75 441 81 486 49 548 56 600 28" fill="none" stroke="#d9a64f" stroke-width="2.5"/><circle cx="600" cy="28" r="4" fill="#F7B955" stroke="white" stroke-width="2"/>${[5,6,7,8,9,10].map((n,i)=>`<text x="${30+i*114}" y="171" text-anchor="middle">${String(n).padStart(2,'0')}</text>`).join('')}</svg><div class="legend"><span><i></i>${txt('حسابات جديدة')}</span></div></div></section><section class="card">${cardHead('حالة الاشتراكات','توزيع الحسابات حسب الحالة')}<div class="subscription-breakdown"><div class="bar-stack">${states.map((s,i)=>`<i style="width:${companies.filter(c=>c.status===s).length/companies.length*100}%;background:${['#101d35','#8aa6c8','#f7b955','#d78c91','#bdc7d5'][i]}"></i>`).join('')}</div>${states.map((s,i)=>`<div class="breakdown-row"><i style="background:${['#101d35','#8aa6c8','#f7b955','#d78c91','#bdc7d5'][i]}"></i>${txt(statusNames[s])}<strong>${companies.filter(c=>c.status===s).length}</strong><small>${Math.round(companies.filter(c=>c.status===s).length/companies.length*100)}%</small></div>`).join('')}</div></section></div><div class="two-col"><section class="card">${cardHead('أحدث حسابات الزبائن','',`<button class="text-btn" data-page="accounts">${txt('عرض الكل')}${icon('arrow')}</button>`)}${accountTable(companies.slice(0,4),true)}</section><section class="card">${cardHead('تنبيهات تحتاج انتباهك','',`<span class="notice-count">3</span>`)}<div class="alert-list">${[['تفعيل بانتظار المراجعة','VX-1004'],['اشتراك ينتهي قريباً','VX-1005'],['اشتراك منتهي','VX-1006']].map(([n,id])=>{const c=companies.find(c=>c.id===id);return `<div class="alert-row"><span class="alert-icon">${icon('clock')}</span><div><h3>${txt(n)}</h3><p>${esc(cName(c))}</p></div><button class="text-btn" data-account="${id}">${txt('مراجعة')}</button></div>`}).join('')}<div class="alert-row"><span class="alert-icon">${icon('servers')}</span><div><h3>${txt('الخادم غير مربوط')}</h3><p>${txt('اربط Asterisk لعرض حالة الاتصال الفعلية وأحداث المكالمات.')}</p><button class="text-btn" data-page="servers">${txt('إعداد الربط')}</button></div></div></div></section></div>`}
function accountTable(cs,compact=false){return `<div class="table-wrap"><table><thead><tr><th>${txt('الشركة')}</th><th>${txt('الباقة')}</th><th>${txt('الحالة')}</th>${compact?'':`<th>${txt('المستخدمون')}</th><th>${txt('تاريخ الانتهاء')}</th>`}<th></th></tr></thead><tbody>${cs.length?cs.map(c=>`<tr><td>${companyCell(c)}</td><td>${esc(planName(c.plan))}</td><td>${badge(c.status)}</td>${compact?'':`<td><span class="number">${c.users}</span></td><td><span class="number">${date(c.end)}</span></td>`}<td><button class="row-link" data-account="${esc(c.id)}">${compact?icon('arrow'):txt('عرض الحساب')}</button></td></tr>`).join(''):`<tr><td colspan="6" class="empty-row">${txt('لا توجد نتائج تطابق البحث')}</td></tr>`}</tbody></table></div>`}
function filterUI(){return `<div class="filters"><div class="search">${icon('search')}<input id="search" value="${esc(query)}" placeholder="${txt('بحث باسم الشركة أو رقم الحساب')}" aria-label="${txt('بحث باسم الشركة أو رقم الحساب')}"></div><select id="filter" aria-label="${txt('الحالة')}"><option value="all">${txt('جميع الحالات')}</option>${Object.keys(statusNames).slice(0,5).map(s=>`<option value="${s}" ${filter===s?'selected':''}>${txt(statusNames[s])}</option>`).join('')}</select></div>`}function filtered(){return companies.filter(c=>(filter==='all'||c.status===filter)&&[c.name,c.english,c.id,c.contact].some(s=>s.toLowerCase().includes(query.toLowerCase())))}
