const previewSettings={platform:'VODNOX',support:'',defaultLanguage:'ar',currency:'IQD',timezone:'Asia/Baghdad',policies:[true,false,false]};const integrationSettings={};
function savePreviewSettings(){const f=$('#settingsForm');if(!f.reportValidity())return;Object.assign(previewSettings,Object.fromEntries(new FormData(f)));toast('حفظ التعديلات في المعاينة فقط')}
function settingsPage(){return head('إعدادات المنصة','اللغة والعملة والتنبيهات وسياسات الاشتراكات.')+`<div class="settings-layout"><section class="card">${cardHead('بيانات المنصة')}<form id="settingsForm" class="settings-body"><div class="form-grid">${field('اسم المنصة','platform',previewSettings.platform)}${field('بريد الدعم','support',previewSettings.support,'email')}${selectField('اللغة الافتراضية','defaultLanguage',[['ar',t('العربية')],['en',t('الإنجليزية')]],previewSettings.defaultLanguage)}${selectField('العملة','currency',[['IQD',t('د.ع')]],'IQD')}${field('المنطقة الزمنية','timezone',previewSettings.timezone,'text',false,'full')}</div><div style="margin-top:23px">${btn('حفظ الإعدادات','saveSettings','','primary')}</div></form></section><section class="card">${cardHead('سياسات الاشتراكات')}<div class="settings-body">${[['تنبيه قبل الانتهاء',previewSettings.policies[0]],['فترة سماح',previewSettings.policies[1]],['التعليق التلقائي',previewSettings.policies[2]]].map(([s,v],i)=>`<div class="toggle-line"><div><b>${txt(s)}</b><p>${txt('تُحدد لاحقاً')}</p></div><button class="switch" role="switch" aria-label="${txt(s)}" aria-checked="${v}" data-action="toggle" data-id="${i}"></button></div>`).join('')}<p class="help-note">${txt('إعدادات المعاينة فقط؛ لا تنفذ أي جدولة أو تعليق فعلي.')}</p></div></section></div>`}
const permissionKeys=['إدارة الحسابات','إدارة الاشتراكات','إدارة الفواتير','إدارة الخوادم','قراءة التقارير'];
const roles=[{name:'مالك المنصة',permissions:[true,true,true,true,true]},{name:'مسؤول اشتراكات',permissions:[true,true,false,false,true]},{name:'مسؤول مالي',permissions:[false,false,true,false,true]},{name:'مسؤول تقني',permissions:[false,false,false,true,true]},{name:'قراءة فقط',permissions:[false,false,false,false,true]}];
function teamPage(){return head('الفريق والصلاحيات','إدارة فريق المنصة وتحديد صلاحيات الإدارة.')+`<div class="section-note">${txt('هذه أدوار مقترحة للتصميم، والصلاحيات الفعلية تُطبّق في Backend عند التنفيذ.')}</div><section class="card">${cardHead('الصلاحيات')}<div class="table-wrap"><table><thead><tr><th>${txt('الدور')}</th>${permissionKeys.map(k=>`<th>${txt(k)}</th>`).join('')}<th></th></tr></thead><tbody>${roles.map((r,i)=>`<tr><td>${txt(r.name)}</td>${r.permissions.map(v=>`<td style="color:${v?'var(--green)':'#bec7d3'}">${v?icon('check'):'—'}</td>`).join('')}<td>${i===0?'<span class="tag">OWNER</span>':btn('الصلاحيات','permissions',String(i))}</td></tr>`).join('')}</tbody></table></div></section>`}
function accountPage(){const c=companies.find(c=>c.id===accountId);const tabs=[['info','معلومات الحساب'],['subscription','الاشتراكات'],['users','المستخدمون'],['telephony','التحويلات والأرقام'],['ivr','IVR والطوابير'],['usage','الاستخدام'],['recordings','التسجيلات'],['invoices','الفواتير والمدفوعات'],['activity','النشاط']];return `<div class="page-head"><button class="text-btn" data-page="accounts">${icon('arrow')}${txt('عودة إلى الحسابات')}</button><span class="tag">TENANT ACCOUNT</span></div><section class="account-header"><span class="company-avatar">${esc(cName(c).charAt(0))}</span><div><h1>${esc(cName(c))}</h1><div class="account-meta"><span class="number">${c.id}</span>${badge(c.status)}<span>${esc(planName(c.plan))}</span><span>${txt('تجهيز الاتصال')}: ${txt('غير مجهّز')}</span></div></div><div class="head-actions">${btn(c.status==='pending'?'تفعيل اشتراك':'تجديد الاشتراك','activate',c.id,'primary','subscriptions')}${btn(c.status==='suspended'?'إعادة تفعيل الحساب':'تعليق الحساب',c.status==='suspended'?'activate':'suspend',c.id)}</div></section><div class="tabs" role="tablist">${tabs.map(([id,s])=>`<button class="tab ${accountTab===id?'active':''}" data-account-tab="${id}" role="tab" aria-selected="${accountTab===id}">${txt(s)}</button>`).join('')}</div>${accountBody(c)}`}
function accountBody(c){if(accountTab==='info')return `<div class="details-grid"><section class="card">${cardHead('ملف الشركة','',btn('التفاصيل','editAccount',c.id))}<dl class="detail-list">${line('اسم الشركة',esc(cName(c)))}${line('اسم المسؤول',esc(c.contact))}${line('البريد الإلكتروني',`<span class="number">${esc(c.email)}</span>`)}${line('رقم الهاتف',c.phone?esc(c.phone):'—')}${line('المدينة',txt(c.city))}${line('تاريخ الإنشاء',`<span class="number">${date(c.created)}</span>`)}</dl></section><section class="card">${cardHead('معلومات الحساب')}<dl class="detail-list">${line('معرّف الشركة',`<span class="number">${c.id}</span>`)}${line('الاشتراك الإداري',badge(c.status))}${line('تجهيز الاتصال',badge('غير مربوط'))}${line('المستخدمون',c.users)}${line('التحويلات الداخلية',c.extensions)}${line('فصل بيانات الشركات',txt('مطلوب عند التنفيذ'))}</dl></section><section class="card">${cardHead('ملاحظات داخلية')}<div class="settings-body"><p class="help-note">${esc(c.notes)||txt('لا توجد ملاحظات')}</p></div></section><section class="card">${cardHead('سياسة الاحتفاظ')}<div class="settings-body"><p class="help-note">${txt('إعداد سياسات الاحتفاظ والحماية لاحقاً')}</p></div></section></div>`;
if(accountTab==='subscription')return `<div class="details-grid"><section class="card">${cardHead('إعدادات الاشتراك')}<dl class="detail-list">${line('الباقة',esc(planName(c.plan)))}${line('الحالة',badge(c.status))}${line('دورة الفوترة',txt(c.cycle==='yearly'?'سنوي':'شهري'))}${line('تاريخ البداية',`<span class="number">${date(c.start)}</span>`)}${line('تاريخ الانتهاء',`<span class="number">${date(c.end)}</span>`)}</dl><div class="detail-actions">${btn('تجديد الاشتراك','activate',c.id,'primary')}${btn('تعليق الحساب','suspend',c.id)}</div></section><section class="card">${cardHead('الباقات وحدود الاستخدام')}<dl class="detail-list">${['المستخدمون المسموحون','المكالمات المتزامنة','مساحة التسجيلات','التحويلات الداخلية'].map(k=>{const p=plans.find(p=>p.id===c.plan);const n={'المستخدمون المسموحون':'users','المكالمات المتزامنة':'concurrent','مساحة التسجيلات':'storage','التحويلات الداخلية':'extensions'}[k];return line(k,p[n]===null?txt('غير محدد'):esc(p[n]))}).join('')}</dl></section></div><div class="section-note" style="margin-top:20px">${txt('تفعيل الوصول لا يعني نجاح تجهيز SIP')}</div>`;
if(accountTab==='users')return `<section class="card">${cardHead('المستخدمون','تجريبي للتصميم',`<span class="tag">${c.users} ${txt('المستخدمون')}</span>`)}<div class="table-wrap"><table><thead><tr>${['اسم المستخدم','الدور','الحالة'].map(s=>`<th>${txt(s)}</th>`).join('')}</tr></thead><tbody>${Array.from({length:Math.min(4,c.users)},(_,i)=>`<tr><td><span class="number">${esc(c.id.toLowerCase())}.${i===0?'admin':'user'+i}</span></td><td>${txt(i===0?'مسؤول الشركة':i===1?'مشرف':'موظف اتصال')}</td><td>${badge(c.status==='active'?'active':'pending')}</td></tr>`).join('')}</tbody></table></div></section>`;
if(accountTab==='telephony')return `<div class="section-note">${txt('لا يوجد ربط فعلي بالخادم. الحسابات أدناه أمثلة للتصميم فقط.')}</div><section class="card">${cardHead('التحويلات الداخلية')}<div class="table-wrap"><table><thead><tr>${['التحويلات الداخلية','اسم المستخدم','التسجيل على SIP'].map(s=>`<th>${txt(s)}</th>`).join('')}</tr></thead><tbody>${Array.from({length:Math.min(4,c.extensions)},(_,i)=>`<tr><td><span class="number">${1001+i}</span></td><td><span class="number">${esc(c.id.toLowerCase())}.user${i+1}</span></td><td>${badge('غير متحقق')}</td></tr>`).join('')||`<tr><td class="empty-row" colspan="3">${txt('غير مجهّز')}</td></tr>`}</tbody></table></div></section><section class="card" style="margin-top:20px">${empty('لا توجد أرقام خارجية مربوطة','ربط الأرقام الخارجية يتطلب إعداد SIP Trunk أو بوابة مناسبة لاحقاً.','phone')}</section>`;
if(accountTab==='ivr')return `<div class="section-note">${txt('الإعدادات المعروضة مسودات، وليست خدمات مفعّلة على Asterisk.')}</div><section class="card">${cardHead('IVR والطوابير')}<div class="table-wrap"><table><thead><tr>${['الاسم','النوع','الحالة'].map(s=>`<th>${txt(s)}</th>`).join('')}</tr></thead><tbody><tr><td>${txt('القائمة الرئيسية')}</td><td>${txt('القائمة الصوتية')}</td><td>${badge('draft')}</td></tr><tr><td>${txt('خدمة العملاء')}</td><td>${txt('طابور اتصال')}</td><td>${badge('draft')}</td></tr></tbody></table></div></section>`;
if(accountTab==='recordings')return `<section class="card">${empty('لا توجد تسجيلات فعلية','تُعرض التسجيلات بعد ربط خادم الاتصالات، مع صلاحيات الوصول وسياسة الاحتفاظ الخاصة بالشركة.','record')}</section>`;
if(accountTab==='usage')return `<section class="card">${cardHead('الاستخدام','بيانات استخدام تجريبية')}<div class="mini-metrics">${[['المكالمات',c.calls],['دقائق الاتصال',c.minutes],['مساحة مستخدمة','—']].map(([k,v])=>`<div class="mini-metric"><span>${txt(k)}</span><strong>${typeof v==='number'?num(v):v}</strong></div>`).join('')}</div></section><section class="card" style="margin-top:20px">${cardHead('سجل مكالمات تجريبي')}<div class="table-wrap"><table><thead><tr>${['تاريخ','الاتجاه','التحويلات الداخلية','المدة','الحالة','التسجيل'].map(s=>`<th>${txt(s)}</th>`).join('')}</tr></thead><tbody>${c.calls?[['10/10/2026 · 14:12','داخلية','1001 → 1002','03:24','تم الرد'],['10/10/2026 · 13:45','داخلية','1002 → 1001','00:00','لم يتم الرد']].map(r=>`<tr>${r.map((v,i)=>`<td>${i===0||i===2||i===3?`<span class="number">${esc(v)}</span>`:txt(v)}</td>`).join('')}<td>${txt('لا يوجد')}</td></tr>`).join(''):`<tr><td colspan="6" class="empty-row">${txt('لا توجد نتائج تطابق البحث')}</td></tr>`}</tbody></table></div></section>`;
if(accountTab==='invoices')return `<section class="card">${cardHead('الفواتير والمدفوعات','تجريبي للتصميم')}${invoiceTable(invoices.filter(i=>i.company===c.id))}</section>`;
return `<section class="card">${cardHead('النشاط','تجريبي للتصميم')}<div class="timeline">${audits.filter(a=>a.company===c.id).map(a=>`<div class="timeline-item"><h3>${esc(lang==='en'?a.en:a.action)}</h3><p>${txt('owner')}</p><time class="number">${esc(a.time)}</time></div>`).join('')||`<div class="timeline-item"><h3>${txt('تاريخ الإنشاء')}</h3><time>${date(c.created)}</time></div>`}</div></section>`}
function render(){nav();$('#crumb').textContent=page==='account'?cName(companies.find(c=>c.id===accountId)):t(page);const renders={overview,accounts:accountsPage,subscriptions:subscriptionsPage,plans:plansPage,billing:billingPage,usage:usagePage,servers:serversPage,integrations:integrationsPage,audit:auditPage,settings:settingsPage,team:teamPage,account:accountPage};$('#content').innerHTML=renders[page]();$('#sidebar').classList.remove('open');document.title=`VODNOX | ${$('#crumb').textContent}`;const s=$('#search');if(s)s.addEventListener('input',()=>{query=s.value;$('#filteredTable').innerHTML=page==='subscriptions'?subscriptionsTable(filtered()):accountTable(filtered())});const f=$('#filter');if(f)f.addEventListener('change',()=>{filter=f.value;$('#filteredTable').innerHTML=page==='subscriptions'?subscriptionsTable(filtered()):accountTable(filtered())});const sf=$('#settingsForm');if(sf)sf.addEventListener('submit',e=>{e.preventDefault();savePreviewSettings()})}
function navigate(p){page=p;query='';filter='all';history.replaceState(null,'','#'+p);render();window.scrollTo(0,0)}function openAccount(id,tab='info'){accountId=id;accountTab=tab;navigate('account')}
function modal(title,body,submit,handler){$('#modalTitle').textContent=t(title);$('#modalBody').innerHTML=body;$('#modalSubmit').textContent=t(submit);modalHandler=handler;$('#modal').showModal()}
function companyForm(c=null){return `<div class="form-grid">${field('اسم الشركة','name',c?.name||'','text',true)}${field('اسم المسؤول','contact',c?.contact||'','text',true)}${field('البريد الإلكتروني','email',c?.email||'','email',true)}${field('رقم الهاتف','phone',c?.phone||'','tel')}${field('المدينة','city',c?.city||'بغداد')}${selectField('الباقة','plan',plans.map(p=>[p.id,t(p.name)]),c?.plan||'team')}<div class="form-field full"><label for="f-notes">${txt('ملاحظات داخلية')}</label><textarea name="notes" id="f-notes">${esc(c?.notes||'')}</textarea></div></div>`}
function activate(id){let c=companies.find(c=>c.id===id)||companies.find(c=>c.status==='pending')||companies[0];const startDate=c.end&&c.end>'2026-10-11'?c.end:'2026-10-11';const expiry=new Date(startDate+'T12:00:00Z');if(c.cycle==='yearly')expiry.setUTCFullYear(expiry.getUTCFullYear()+1);else expiry.setUTCMonth(expiry.getUTCMonth()+1);const endDate=expiry.toISOString().slice(0,10);modal('تفعيل اشتراك',`<div class="section-note">${txt('التفعيل الإداري منفصل عن تجهيز خدمات الاتصال على الخادم.')}</div><div class="form-grid">${selectField('اختر الشركة','company',companies.map(c=>[c.id,cName(c)]),c.id)}${selectField('اختر الباقة','plan',plans.map(p=>[p.id,t(p.name)]),c.plan)}${selectField('دورة الفوترة','cycle',[['monthly',t('شهري')],['yearly',t('سنوي')]],c.cycle)}${selectField('الحالة','status',[['active',t('فعّال')],['trial',t('تجريبي')]],c.status==='trial'?'trial':'active')}${field('تاريخ البداية','start',startDate,'date',true)}${field('تاريخ الانتهاء','end',endDate,'date',true)}</div>`, 'تفعيل تجريبي', data=>{if(data.end<=data.start){toast('تاريخ الانتهاء يجب أن يكون بعد تاريخ البداية.');return false}c=companies.find(c=>c.id===data.company);Object.assign(c,{plan:data.plan,cycle:data.cycle,status:data.status,start:data.start,end:data.end});log('تم تحديث الاشتراك في المعاينة',c.id);toast('تم تحديث الاشتراك في المعاينة');return true})}
function editPlan(id){const p=plans.find(p=>p.id===id);modal(p?'تعديل الباقة':'إنشاء باقة',`<div class="section-note">${txt('الباقات المعروضة مسودات للتصميم. الأسعار والحدود لم تُعتمد، ويمكن إعدادها لكل باقة.')}</div><div class="form-grid">${field('اسم الباقة','name',p?.name||'','text',true)}${field('وصف الباقة','desc',p?.desc||'')}${field('السعر الشهري (د.ع)','monthly',p?.monthly??'','number')}${field('السعر السنوي (د.ع)','yearly',p?.yearly??'','number')}${field('المستخدمون المسموحون','users',p?.users??'','number')}${field('التحويلات الداخلية','extensions',p?.extensions??'','number')}${field('المكالمات المتزامنة','concurrent',p?.concurrent??'','number')}${field('مساحة التسجيلات','storage',p?.storage??'','number')}</div><p class="help-note">${txt('اتركه فارغاً حتى اعتماد التسعير')} · ${txt('مساحة التسجيلات')}: GB</p>`, 'save',data=>{const values={name:data.name,desc:data.desc};for(const key of ['monthly','yearly','users','extensions','concurrent','storage'])values[key]=data[key]===''?null:Number(data[key]);if(p)Object.assign(p,values);else plans.push({id:'plan'+Date.now(),...values});toast('تم حفظ الباقة كمسودة');return true})}
function exportCSV(type){let rows;if(type==='exportInvoices')rows=[['Invoice','Company','Amount IQD','Due','Status'],...invoices.map(i=>[i.id,i.company,i.amount,i.due,i.status])];else if(type==='exportUsage')rows=[['Company','Account','Calls','Minutes','Users','Extensions'],...companies.map(c=>[cName(c),c.id,c.calls,c.minutes,c.users,c.extensions])];else rows=[['Company','Account','Status','Plan','Start','End'],...companies.map(c=>[cName(c),c.id,c.status,planName(c.plan),c.start,c.end])];const cell=v=>{let s=String(v);if(/^[=+@\-]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"'};const u=URL.createObjectURL(new Blob(['\uFEFF'+rows.map(r=>r.map(cell).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8;'}));const a=document.createElement('a');a.href=u;a.download='vodnox-demo-'+type+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);toast('تم تصدير البيانات التجريبية')}
function action(n,id,el){if(n==='permissions'){const r=roles[Number(id)];return modal('تحديد صلاحيات الدور',`<div class="section-note">${txt(r.name)}</div>${permissionKeys.map((k,i)=>`<div class="toggle-line"><label for="permission-${i}">${txt(k)}</label><input type="checkbox" id="permission-${i}" name="permission${i}" ${r.permissions[i]?'checked':''}></div>`).join('')}`,'save',data=>{r.permissions=permissionKeys.map((_,i)=>data['permission'+i]==='on');toast('حفظ التعديلات في المعاينة فقط');return true})}if(n==='activate')return activate(id);if(n==='addAccount'||n==='editAccount'){const c=companies.find(c=>c.id===id);return modal(c?'ملف الشركة':'إضافة حساب',companyForm(c),'حفظ الحساب',data=>{if(c)Object.assign(c,{name:data.name,english:data.name,contact:data.contact,email:data.email,phone:data.phone,city:data.city,plan:data.plan,notes:data.notes});else{const newId='VX-'+(1001+companies.length);companies.unshift({id:newId,name:data.name,english:data.name,contact:data.contact,email:data.email,phone:data.phone,city:data.city,plan:data.plan,notes:data.notes,status:'pending',cycle:'monthly',start:'',end:'',users:0,extensions:0,calls:0,minutes:0,created:'2026-10-11'});log('تم إنشاء الحساب التجريبي',newId)}toast(c?'حفظ التعديلات في المعاينة فقط':'تم إنشاء الحساب التجريبي');return true})}if(n==='suspend'){const c=companies.find(c=>c.id===id);return modal('تعليق الحساب',`<div class="section-note">${esc(cName(c))}<br>${txt('لن يتغير وضع المكالمات الفعلي؛ لا يوجد ربط بخادم الاتصالات.')}</div>${field('سبب التعليق','reason','','text',true)}`,'تأكيد التعليق',data=>{c.status='suspended';c.notes=data.reason;log('تم تعليق الحساب في المعاينة',c.id);toast('تم تعليق الحساب في المعاينة');return true})}if(n==='editPlan'||n==='addPlan')return editPlan(id);if(n==='checkServer')return toast('تعذّر الفحص: لم يتم إعداد ربط Asterisk في هذه المعاينة.');if(n==='integration')return modal('إعدادات الربط',`<div class="section-note">${txt('لا تُدخل كلمات مرور أو مفاتيح حقيقية في رابط المعاينة العام.')}</div><div class="form-grid">${field('الاسم','service',id,'text',true)}${field('عنوان الخدمة','url',integrationSettings[id]?.url||'','url')}<div class="form-field full"><label>${txt('الحالة')}</label>${badge('غير مربوط')}</div></div><p class="help-note">${txt('لا توجد مفاتيح أو بيانات اعتماد محفوظة في هذه المعاينة.')}</p>`,'save',data=>{integrationSettings[id]={url:data.url,name:data.service};toast('حفظ التعديلات في المعاينة فقط');return true});if(n==='pay'){const i=invoices.find(i=>i.id===id);return modal('تسجيل دفعة',`<div class="section-note">${txt('سجّل دفعة تجريبية لهذه الفاتورة. لن تتم أي عملية دفع فعلية.')}</div><div class="form-grid">${field('رقم الفاتورة','invoice',i.id)}${field('المبلغ','amount',i.amount,'number',true)}${selectField('طريقة الدفع','method',[['bank',t('تحويل مصرفي')],['cash',t('نقدي')]])}${field('مرجع الدفعة','reference','','text',true)}</div>`,'تأكيد التسجيل',data=>{if(Number(data.amount)!==i.amount){toast(lang==='ar'?'لهذه المعاينة، سجّل مبلغ الفاتورة كاملاً.':'For this preview, record the full invoice amount.');return false}i.status='paid';log('تم تسجيل الدفعة التجريبية',i.company);toast('تم تسجيل الدفعة التجريبية');return true})}if(n==='invoice')return modal('إصدار فاتورة',`<div class="section-note">${txt('الأرقام المالية هنا أمثلة للعرض، وليست أسعار باقات معتمدة.')}</div><div class="form-grid">${selectField('الشركة','company',companies.map(c=>[c.id,cName(c)]))}${field('المبلغ','amount','','number',true)}${field('الاستحقاق','due','2026-11-01','date',true)}</div>`,'save',data=>{if(Number(data.amount)<=0){toast(lang==='ar'?'أدخل مبلغاً أكبر من صفر.':'Enter an amount greater than zero.');return false}invoices.push({id:'INV-DEMO-'+(invoices.length+1),company:data.company,amount:Number(data.amount),due:data.due,status:'unpaid'});log(lang==='ar'?'إنشاء فاتورة تجريبية':'Sample invoice created',data.company);toast('حفظ التعديلات في المعاينة فقط');return true});if(n.startsWith('export'))return exportCSV(n);if(n==='toggle'){const next=el.getAttribute('aria-checked')!=='true';el.setAttribute('aria-checked',String(next));previewSettings.policies[Number(id)]=next;return toast('حفظ التعديلات في المعاينة فقط')}if(n==='saveSettings')savePreviewSettings()}
document.addEventListener('click',e=>{const p=e.target.closest('[data-page]');if(p)return navigate(p.dataset.page);const a=e.target.closest('[data-account]');if(a)return openAccount(a.dataset.account,a.dataset.tab||'info');const tab=e.target.closest('[data-account-tab]');if(tab){accountTab=tab.dataset.accountTab;render();return}const b=e.target.closest('[data-action]');if(b){e.preventDefault();action(b.dataset.action,b.dataset.id||'',b)}});$('#modalForm').addEventListener('submit',e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));if(modalHandler(d)!==false){$('#modal').close();render()}});$('#cancelModal').onclick=$('#closeModal').onclick=()=>$('#modal').close();$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}});$('#language').onclick=()=>{lang=lang==='ar'?'en':'ar';document.documentElement.lang=lang;document.documentElement.dir=lang==='ar'?'rtl':'ltr';render()};$('#menuBtn').onclick=()=>$('#sidebar').classList.toggle('open');$('#notifications').onclick=()=>modal('تنبيهات تحتاج انتباهك',companies.filter(c=>['pending','expired'].includes(c.status)||c.id==='VX-1005').map(c=>`<div class="detail-line"><span>${esc(cName(c))}</span>${badge(c.status)}</div>`).join(''),'save',()=>true);document.addEventListener('keydown',e=>{if(e.key==='Escape')$('#sidebar').classList.remove('open')});const initial=location.hash.slice(1);if(['overview','accounts','subscriptions','plans','billing','usage','servers','integrations','team','audit','settings'].includes(initial))page=initial;render();
